begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select ok(not has_table_privilege('authenticated', 'private.parley_references', 'SELECT'), 'Private source documents are not client-readable');
select ok(not has_table_privilege('anon', 'private.parley_scenarios', 'SELECT'), 'Anonymous clients cannot read scenarios');
select ok(not has_table_privilege('authenticated', 'private.parley_members', 'UPDATE'), 'Accounts cannot allowlist themselves');
select ok(not has_function_privilege('authenticated', 'public.create_parley_session(uuid,uuid,uuid)', 'EXECUTE'), 'Session creation requires server authorization');
select ok(not has_function_privilege('authenticated', 'private.begin_meeting_ai_live_session(uuid,uuid,uuid,text,timestamptz,text,uuid)', 'EXECUTE'), 'Clients cannot forge billing provenance');
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('private.parley_references'::regclass, 'private.parley_scenarios'::regclass, 'private.parley_members'::regclass, 'private.parley_sessions'::regclass, 'private.parley_observations'::regclass)), 'Every research table enables RLS');

insert into public.users(id, display_name) values ('34000000-0000-4000-8000-000000001001', 'Meeting billing test');
insert into public.workspaces(id, name, creator_id, personal) values ('34000000-0000-4000-8000-000000001010', 'Meeting billing test', '34000000-0000-4000-8000-000000001001', false);
insert into public.workspace_members(ws_id, user_id, type) values ('34000000-0000-4000-8000-000000001010', '34000000-0000-4000-8000-000000001001', 'MEMBER') on conflict do nothing;
insert into public.workspace_meetings(id, ws_id, creator_id, name, time) values ('34000000-0000-4000-8000-000000001011', '34000000-0000-4000-8000-000000001010', '34000000-0000-4000-8000-000000001001', 'Generic billing fixture', now());
insert into public.workspace_ai_credit_balances(id, ws_id, period_start, period_end, total_allocated, total_used) values ('34000000-0000-4000-8000-000000001020', '34000000-0000-4000-8000-000000001010', date_trunc('month', now()), date_trunc('month', now()) + interval '1 month', 10000, 0);
create temporary table started as select * from private.begin_meeting_ai_live_session('34000000-0000-4000-8000-000000001001', '34000000-0000-4000-8000-000000001010', '34000000-0000-4000-8000-000000001010', 'gemini-3.1-flash-live-preview', now() + interval '5 minutes', 'parley', '34000000-0000-4000-8000-000000001011');
select is((select success from started), true, 'Parley reserves credits before provider execution');
select is((select metadata->>'app' from private.ai_credit_reservations where id = (select reservation_id from started)), 'parley', 'Reservation is attributed to Parley');
create temporary table settled as select * from private.settle_ai_live_session((select live_session_id from started), '34000000-0000-4000-8000-000000001001', 1, '{"inputTextTokens":1000,"inputAudioTokens":0,"inputImageTokens":0,"inputVideoTokens":0,"outputTextTokens":0,"outputAudioTokens":0,"thinkingTokens":0,"searchQueries":0}', true);
select is((select success from settled), true, 'Provider usage is settled');
select is((select metadata->>'app' from public.ai_credit_transactions where metadata->>'live_session_id' = (select live_session_id::text from started)), 'parley', 'Final credit ledger retains application attribution');
select is((select total_used from public.workspace_ai_credit_balances where id = (select balance_id from private.ai_credit_reservations where id = (select reservation_id from started))), (select billed_credits from settled), 'Unused held credits are refunded');
select is((select source_id from private.collect_ai_studio_consumption_events('34000000-0000-4000-8000-000000001010', '34000000-0000-4000-8000-000000001001', now() - interval '1 day', now() + interval '1 day') where request_id like 'credit:%'), 'app:parley', 'AI Hub displays the Parley credit event');
select lives_ok($$select * from private.settle_ai_live_session((select live_session_id from started), '34000000-0000-4000-8000-000000001001', 1, '{"inputTextTokens":1000,"inputAudioTokens":0,"inputImageTokens":0,"inputVideoTokens":0,"outputTextTokens":0,"outputAudioTokens":0,"thinkingTokens":0,"searchQueries":0}', true)$$, 'Settlement replay is accepted idempotently');
select is((select count(*) from public.ai_credit_transactions where metadata->>'live_session_id' = (select live_session_id::text from started)), 1::bigint, 'Settlement retry never double charges');
select throws_ok($$select * from private.begin_meeting_ai_live_session('34000000-0000-4000-8000-000000001001', '34000000-0000-4000-8000-000000001010', '34000000-0000-4000-8000-000000001010', 'gemini-3.1-flash-live-preview', now(), 'other', '34000000-0000-4000-8000-000000001011')$$, 'P0001', 'Invalid meeting app', 'Unknown application provenance is rejected');
-- Chat must settle from its own reservation even when no spare credits remain.
update public.workspace_ai_credit_balances set total_allocated = total_used + 30, bonus_credits = 0 where id = (select balance_id from private.ai_credit_reservations where id = (select reservation_id from started));
create temporary table chat_started as select * from private.begin_ai_studio_run('meeting-chat-test', '34000000-0000-4000-8000-000000001010', '34000000-0000-4000-8000-000000001001', null, 'google/gemini-3.1-flash-lite', 'chat', 30, 'meeting-chat-test', '{"app":"meet","source":"meet_mira_personal"}');
select is((select success from chat_started), true, 'Meet chat reserves the last available credits');
create temporary table chat_settled as select * from private.settle_ai_studio_run(p_run_id => (select run_id from chat_started), p_status => 'succeeded', p_actual_credits => 20, p_provider_cost_usd => 0.001, p_input_tokens => 100, p_output_tokens => 20, p_metadata => '{"search_count":3}');
select is((select success from chat_settled), true, 'Chat settles against its own hold without a second deduction');
select is((select remaining_credits from chat_settled), 10::numeric, 'Chat refunds exactly the unused reservation');
select is((select source_id from private.collect_ai_studio_consumption_events('34000000-0000-4000-8000-000000001010', '34000000-0000-4000-8000-000000001001', now() - interval '1 day', now() + interval '1 day') where event_id = (select run_id from chat_started)), 'app:meet', 'AI Hub attributes the chat run to Meet without duplicate ledger consumption');
select is((select search_units from private.collect_ai_studio_consumption_events('34000000-0000-4000-8000-000000001010', '34000000-0000-4000-8000-000000001001', now() - interval '1 day', now() + interval '1 day') where event_id = (select run_id from chat_started)), 3::bigint, 'AI Hub retains measured search usage from the chat run');
select throws_ok($$select * from private.begin_meeting_ai_live_session('34000000-0000-4000-8000-000000001001', '34000000-0000-4000-8000-000000001010', '34000000-0000-4000-8000-000000001010', 'gemini-3.1-flash-live-preview', now() + interval '5 minutes', null, '34000000-0000-4000-8000-000000001011')$$, 'P0001', 'Invalid meeting app', 'Missing application provenance is rejected');
insert into public.workspaces(id, name, creator_id, personal) values ('34000000-0000-4000-8000-000000001030', 'Other billing test workspace', '34000000-0000-4000-8000-000000001001', false);
select throws_ok($$select * from private.begin_meeting_ai_live_session('34000000-0000-4000-8000-000000001001', '34000000-0000-4000-8000-000000001030', '34000000-0000-4000-8000-000000001010', 'gemini-3.1-flash-live-preview', now() + interval '5 minutes', 'parley', '34000000-0000-4000-8000-000000001011')$$, 'P0001', 'Invalid meeting workspace', 'Meetings outside the access workspace are rejected');
select * from finish();
rollback;
